#!/usr/bin/env python3
"""Encode generated source PNGs for LVGL; originals remain byte-for-byte intact.

ImageMagick performs deterministic atlas extraction and nearest-neighbour fitting
to the native pixel grid. This is a build-time asset export, never runtime scaling.
Runtime C outputs are versioned; source PNGs and provenance.json retain the originals.
"""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import re
import tempfile

ROOT = Path(__file__).resolve().parent


def encode(out):
    magick = shutil.which('magick')
    if not magick:
        raise SystemExit('ImageMagick 7 (magick) required for the optional companion prototype')
    atlas_size = subprocess.check_output([magick, 'identify', '-format', '%wx%h',
                                         str(ROOT/'source/icons.png')], text=True)
    if atlas_size != '1254x1254':
        raise SystemExit('Unexpected atlas size: update the explicit cell specification before exporting')
    out.mkdir(parents=True, exist_ok=True)
    records = []
    bodies = ['/* Generated by build_assets.py; do not edit. */', '#include "companion_assets.h"']
    declarations = ['#pragma once', '#include "lvgl.h"']

    def asset(name, source, w, h, alpha=False, crop=None):
        args = [magick, str(ROOT / 'source' / source)]
        if crop:
            args += ['-crop', crop, '+repage']
        if alpha:
            # Generated PNGs can contain almost-transparent pixels far outside
            # the visible sprite. Exclude those before fitting its silhouette.
            args += ['-channel', 'A', '-threshold', '50%', '+channel',
                     '-trim', '+repage', '-sample', f'{w//2}x{h//2}',
                     '-gravity', 'center', '-background', 'none', '-extent', f'{w//2}x{h//2}']
        else:
            args += ['-sample', f'{w//2}x{h//2}!']
        args += ['-sample', f'{w}x{h}!', '-depth', '8', 'rgba:-']
        rgba = subprocess.run(args, check=True, stdout=subprocess.PIPE).stdout
        assert len(rgba) == w*h*4, (name, len(rgba))
        if alpha:
            assert 0 in rgba[3::4] and 255 in rgba[3::4], f'{name}: missing silhouette or transparency'
        pixels = bytearray()
        for i in range(0, len(rgba), 4):
            r, g, b, _ = rgba[i:i+4]
            value = ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3)
            pixels += value.to_bytes(2, 'little')
        if alpha:
            pixels += rgba[3::4]
        assert len(pixels) == w*h*(3 if alpha else 2)
        bodies.append(f'_Alignas(4) static const uint8_t {name}_data[] = {{')
        for i in range(0, len(pixels), 24):
            bodies.append('  '+','.join(f'0x{p:02x}' for p in pixels[i:i+24])+',')
        bodies.append('};')
        cf = 'RGB565A8' if alpha else 'RGB565'
        bodies.append(f'const lv_image_dsc_t {name} = {{.header={{.magic=LV_IMAGE_HEADER_MAGIC,'
                      f'.cf=LV_COLOR_FORMAT_{cf},.w={w},.h={h},.stride={w*2}}},'
                      f'.data_size=sizeof {name}_data,.data={name}_data}};')
        declarations.append(f'extern const lv_image_dsc_t {name};')
        records.append(dict(name=name, width=w, height=h, format=cf, bytes=len(pixels),
                            sha256=hashlib.sha256(pixels).hexdigest()))

    asset('companion_camp', 'camp.png', 466, 466)
    asset('companion_hero', 'hero.png', 104, 128, True)
    # The source atlas is 1254 square: 3 columns x 2 rows. No inferred slicing.
    for i, name in enumerate(('sword', 'dice', 'magic', 'pack', 'rest', 'sheet')):
        asset('companion_'+name, 'icons.png', 64, 64, True,
              f'418x627+{(i%3)*418}+{(i//3)*627}')
    asset('companion_dock_dice', 'icons.png', 48, 48, True, '418x627+418+0')
    asset('companion_dock_pack', 'icons.png', 48, 48, True, '418x627+0+627')
    (out/'companion_assets.c').write_text('\n'.join(bodies)+'\n')
    (out/'companion_assets.h').write_text('\n'.join(declarations)+'\n')
    manifest = dict(images=records, image_bytes=sum(r['bytes'] for r in records),
                    sources={p.name: hashlib.sha256(p.read_bytes()).hexdigest()
                             for p in sorted((ROOT/'source').glob('*.png'))},
                    tool=subprocess.check_output([magick, '-version'], text=True).splitlines()[0])
    (out/'assets.json').write_text(json.dumps(manifest, indent=2)+'\n')
    print(f"Companion: {len(records)} images, {manifest['image_bytes']} image bytes (excludes LVGL heap)")


def verify():
    manifest = json.loads((ROOT/'assets.json').read_text())
    for name, digest in manifest['sources'].items():
        assert hashlib.sha256((ROOT/'source'/name).read_bytes()).hexdigest() == digest, name
    source = (ROOT/'companion_assets.c').read_text()
    arrays = dict(re.findall(r'static const uint8_t (\w+)_data\[\] = \{(.*?)\};', source, re.S))
    assert len(arrays) == len(manifest['images'])
    for record in manifest['images']:
        data = bytes(int(value, 16) for value in re.findall(r'0x([0-9a-f]{2})', arrays[record['name']]))
        assert len(data) == record['bytes'] and hashlib.sha256(data).hexdigest() == record['sha256'], record['name']
    assert sum(record['bytes'] for record in manifest['images']) == manifest['image_bytes']
    print('Committed companion assets: source and encoded hashes verified')


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('output', type=Path, nargs='?', default=ROOT)
    parser.add_argument('--verify', action='store_true', help='Check committed hashes; no ImageMagick needed')
    parser.add_argument('--check', action='store_true', help='Re-export to a temporary directory and compare raster C/header')
    args = parser.parse_args()
    if args.verify:
        verify()
    elif args.check:
        verify()
        with tempfile.TemporaryDirectory(prefix='pocketdd-companion-') as directory:
            destination = Path(directory)
            encode(destination)
            for name in ('companion_assets.c', 'companion_assets.h'):
                assert (destination/name).read_bytes() == (ROOT/name).read_bytes(), name
    else:
        encode(args.output)
